const { validate } = require(C + 'validation/validate.ts');
const { OverlappingFieldsCanBeMergedRule } = require(C + 'validation/rules/OverlappingFieldsCanBeMergedRule.ts');

function oldSame(n1, n2) {
  const a1 = n1.arguments ?? [];
  const a2 = n2.arguments ?? [];
