}

describe('scratch', () => {
  it('long numeric names order', () => {
    const schema = buildSchema(`type Query { f(a12345678901234567890: Int, a12345678901234567891: Int): Int }`);
    const errs = validate(schema, parse(`{ f(a12345678901234567890: 1, a12345678901234567891: 2) f(a12345678901234567891: 2, a12345678901234567890: 1) }`), [OverlappingFieldsCanBeMergedRule]);
