      for (let i = 0; i < N; i++) oldSame(n1, n2);
      const o = Number(process.hrtime.bigint() - t) / 1e6;
      t = process.hrtime.bigint();
      for (let i = 0; i < N; i++) newStr(n1) !== newStr(n2);
      const nw = Number(process.hrtime.bigint() - t) / 1e6;
